extern "C" int sprintf(char *, const char *, ...);
extern "C" char *strncpy(char *, const char *, unsigned int);
extern "C" unsigned int strlen(const char *);
class Menu; class MenuSystem;
struct MenuColor { unsigned char r, g, b, a; };
class MenuEntry {
    unsigned int flags;
public:
    MenuEntry(); virtual ~MenuEntry(); virtual MenuColor GetColor(void);
    virtual void Show(void); virtual void Hide(void); virtual void Enable(void); virtual void Disable(void);
    virtual void Activate(void); virtual void Deactivate(void); virtual void OnTick(float);
    virtual void OnMenuOpen(Menu *, MenuSystem *); virtual void OnMenuClose(void);
    virtual void OnButtonPress(int); virtual void OnButtonRelease(int);
protected:
    virtual void OnHide(void); virtual void OnShow(void); virtual void OnEnable(void); virtual void OnDisable(void);
    virtual void OnActivate(void); virtual void OnDeactivate(void);
public:
    virtual int MenuText(char *text, int len) { if (len>0) *text=0; return 0; }
};
class MenuEntryLabel : public MenuEntry {
protected: const char *label;
public: MenuEntryLabel(const char *); virtual ~MenuEntryLabel(); virtual int MenuText(char *, int);
};
class MenuEntryIntEdit : public MenuEntryLabel {
    int *tint;
protected: int lo, hi; int delta; char *format;
public:
    MenuEntryIntEdit(const char *, int *, int, int); MenuEntryIntEdit(const char *, int *, int, int, char *);
    virtual ~MenuEntryIntEdit(); virtual void OnMenuOpen(Menu *, MenuSystem *); virtual int MenuText(char *, int);
    virtual void OnButtonPress(int); void FixValue(void); virtual void DecValue(void); virtual void IncValue(void);
    virtual void DecValueByTen(void); virtual void IncValueByTen(void); virtual void DecValueByFifty(void);
    virtual void IncValueByFifty(void); virtual void SetValue(int); virtual int GetValue(void);
};
class MenuEntryListEdit : public MenuEntryIntEdit {
    char **label;
public:
    MenuEntryListEdit(char *, int *, int, char **); MenuEntryListEdit(char *, int *, int, char **, char *);
    virtual ~MenuEntryListEdit(); virtual int MenuText(char *, int);
};
int MenuEntryListEdit::MenuText( char *text, int len )
{
	if ( len && label )
	{
		int lused=MenuEntryLabel::MenuText(text,len);
		char tval[256];
/*
		char *estr=label[GetValue()];
*/
		if ( format )
		{
			sprintf(tval,format,label[GetValue()]);
		}
		else
		{
			sprintf(tval," : %s",label[GetValue()]);
		}

		strncpy(text+lused,tval,len-lused);
		text[len-1]=0;
		return strlen(text);
	}
	else
		return MenuEntry::MenuText(text,len);
}
